<!--
  数值参数输入框 (配音参数的唯一数值控件)。

  **合成参数一律用数字输入框, 不用滑杆**: 滑杆看不到当前值、也无法精确输入 (温度 1.05 与 1.10
  的差别是听得出来的), 而且占一整行 —— 配音卡的面板高度是写死的, 只有并排的数字框才放得下全部
  参数。步进用 `<input type="number">` 的**原生步进器**, 步长与边界交给 `step` / `min` / `max`。

  输入过程中**不校验** (允许暂时为空、暂时越界), 失焦或回车才夹到范围内并上报, 因此不会出现
  "删到一半就被弹回原值"。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { untrack } from 'svelte';

  /** 参数取值范围 (与 `voice/types.ts` 的 `PARAM_TICKS` 同形) */
  interface Tick {
    min: number;
    max: number;
    step: number;
    default: number;
  }

  let {
    value,
    tick,
    integer = false,
    disabled = false,
    oncommit,
  }: {
    value: number;
    tick: Tick;
    /** 只接受整数 (topK / 种子) */
    integer?: boolean;
    disabled?: boolean;
    oncommit: (value: number) => void;
  } = $props();

  /** 小数位由步长决定 (0.05 → 两位), 整数参数 0 位 */
  function decimalsOf(range: Tick, isInteger: boolean): number {
    if (isInteger) return 0;
    const text = String(range.step);
    const dot = text.indexOf('.');
    return dot < 0 ? 0 : text.length - dot - 1;
  }

  const decimals = $derived(decimalsOf(tick, integer));

  /**
   * 输入框里显示的文本 (可能暂时是空的或越界的, 落定时才夹范围)。
   *
   * 初值用 `untrack` 取: 直接写 `$state(value.toFixed(decimals))` 会被 svelte-check 记一条
   * "只捕获了初值"的警告 —— 真正的同步靠下面那个 effect。
   */
  let text = $state(untrack(() => value.toFixed(decimalsOf(tick, integer))));

  /*
   * 外部值变化时同步显示 (切换语句 / 换角色 / 恢复默认)。
   *
   * 只**读** `value`, 写 `text` 用 `untrack` 包住 —— 否则这个 effect 会把 `text` 也当成依赖,
   * 用户每敲一个字符都会把光标位置重置一遍。
   */
  $effect(() => {
    const next = value.toFixed(decimals);
    untrack(() => (text = next));
  });

  /** 落定一个数值: 夹到范围, 回写显示, 与当前值不同才上报 */
  function apply(raw: number): void {
    if (!Number.isFinite(raw)) {
      text = value.toFixed(decimals);
      return;
    }
    const clamped = Math.min(tick.max, Math.max(tick.min, integer ? Math.round(raw) : raw));
    text = clamped.toFixed(decimals);
    if (clamped !== value) oncommit(clamped);
  }
</script>

<input
  class="ui-input voice-control"
  type="number"
  min={tick.min}
  max={tick.max}
  step={tick.step}
  value={text}
  {disabled}
  title={`${tick.min} ~ ${tick.max}，步长 ${tick.step}`}
  oninput={(event) => (text = event.currentTarget.value)}
  onblur={() => apply(Number.parseFloat(text))}
  onkeydown={(event) => {
    if (event.key === 'Enter') {
      apply(Number.parseFloat(text));
      // 回车落定之后一并失焦 (用户按回车就是"填完了")
      event.currentTarget.blur();
    }
  }}
/>
